global.schema:
type VetraAppState {
  name: String
  slug: String
  owner: EthereumAddress
  status: VetraAppStatus!
  repository: VetraAppRepository
  identity: VetraAppIdentity
  productionEnvironmentId: OID
  previews: VetraAppPreviews
  artifacts: [VetraAppArtifact!]!
  templates: [VetraAppEnvironmentTemplate!]!
  terms: [VetraAppLicenseTerm!]!
}

enum VetraAppStatus {
  PENDING_IDENTITY
  ACTIVE
  DISCONNECTED
  DELETED
}

type VetraAppRepository {
  repositoryId: String
  fullName: String
  productionBranch: String
}

type VetraAppIdentity {
  did: String
  expiresAt: DateTime
}

type VetraAppPreviews {
  enabled: Boolean!
  limit: Int!
  ttlDays: Int!
}

type VetraAppArtifact {
  id: OID!
  kind: VetraAppArtifactKind!
  name: String!
  versions: [VetraAppArtifactVersion!]!
  channels: [VetraAppArtifactChannel!]!
}

enum VetraAppArtifactKind {
  PACKAGE
  FUSION_IMAGE
}

type VetraAppArtifactVersion {
  version: String!
  reference: String!
  commitSha: String
  runId: String
  publishedAt: DateTime!
}

type VetraAppArtifactChannel {
  channel: AutoUpdateChannel!
  version: String!
}

enum AutoUpdateChannel {
  DEV
  STAGING
  LATEST
}

type VetraAppEnvironmentTemplate {
  id: OID!
  name: String
  mode: TemplateInstanceMode!
  sharedEnvironment: PHID
  services: [TemplateService!]!
  packages: [TemplatePackage!]!
  size: String
  baseDomain: String
  packageRegistry: URL
}

enum TemplateInstanceMode {
  SHARED
  DEDICATED
}

type TemplateService {
  id: OID!
  type: TemplateServiceType!
  prefix: String
  artifactName: String
  artifactChannel: AutoUpdateChannel
}

enum TemplateServiceType {
  CONNECT
  SWITCHBOARD
  FUSION
  CLINT
  DOCLING
  PAPERLESS
  SPECKLE
}

type TemplatePackage {
  id: OID!
  packageName: String
  version: String
}

type VetraAppLicenseTerm {
  id: OID!
  kind: String!
  label: String
  templateId: OID
  validityDays: Int
  issuers: [LicenseIssuerKind!]!
  status: LicenseTermStatus!
}

enum LicenseTermStatus {
  DRAFT
  ACTIVE
  RETIRED
}

enum LicenseIssuerKind {
  INVITE_CODE
  PUBLISHER_GRANT
  ACHRA_SUBSCRIPTION
}

operations.schema:
input SetAppDetailsInput {
  name: String
  slug: String
  owner: EthereumAddress
}

operations.reducer:
if (action.input.name) state.name = action.input.name;
if (action.input.slug) state.slug = action.input.slug;
if (action.input.owner) state.owner = action.input.owner;

operations.schema:
input ConnectRepositoryInput {
  repositoryId: String
  fullName: String
  productionBranch: String
}

operations.reducer:
state.repository = {
  repositoryId: action.input.repositoryId ?? null,
  fullName: action.input.fullName ?? null,
  productionBranch: action.input.productionBranch ?? null,
};

operations.schema:
input SetIdentityInput {
  did: String
  expiresAt: DateTime
}

operations.reducer:
state.identity = {
  did: action.input.did ?? null,
  expiresAt: action.input.expiresAt ?? null,
};

operations.schema:
input SetPreviewsInput {
  enabled: Boolean!
  limit: Int!
  ttlDays: Int!
}

operations.reducer:
state.previews = {
  enabled: action.input.enabled,
  limit: action.input.limit,
  ttlDays: action.input.ttlDays,
};

const MAX_ARTIFACT_VERSIONS = 50;

let artifact = state.artifacts.find(
  (a) => a.kind === action.input.kind && a.name === action.input.name,
);
if (!artifact) {
  artifact = {
    id: `${action.input.kind}:${action.input.name}`,
    kind: action.input.kind,
    name: action.input.name,
    versions: [],
    channels: [],
  };
  state.artifacts.push(artifact);
}

const entry = {
  version: action.input.version,
  reference: action.input.reference,
  commitSha: action.input.commitSha ?? null,
  runId: action.input.runId ?? null,
  publishedAt: action.input.publishedAt,
};
const at = artifact.versions.findIndex((v) => v.version === action.input.version);
if (at >= 0) {
  artifact.versions[at] = entry;
} else {
  artifact.versions.push(entry);
}

// A document that grows without bound eventually fails to load, and a dropdown
// never needs the whole history.
if (artifact.versions.length > MAX_ARTIFACT_VERSIONS) {
  artifact.versions = artifact.versions.slice(
    artifact.versions.length - MAX_ARTIFACT_VERSIONS,
  );
}
// A channel aimed at a version the cap dropped is worse than no channel.
artifact.channels = artifact.channels.filter((c) =>
  artifact.versions.some((v) => v.version === c.version),
);

operations.schema:
input SetArtifactChannelInput {
  kind: VetraAppArtifactKind!
  name: String!
  channel: AutoUpdateChannel!
  version: String!
}

operations.reducer:
const artifact = state.artifacts.find(
  (a) => a.kind === action.input.kind && a.name === action.input.name,
);
if (!artifact) {
  throw new UnknownArtifactError(
    `${action.input.kind} ${action.input.name} has published nothing`,
  );
}
if (!artifact.versions.some((v) => v.version === action.input.version)) {
  throw new UnknownArtifactVersionError(
    `${action.input.name} has no published version ${action.input.version}`,
  );
}
const at = artifact.channels.findIndex((c) => c.channel === action.input.channel);
const entry = { channel: action.input.channel, version: action.input.version };
if (at >= 0) {
  artifact.channels[at] = entry;
} else {
  artifact.channels.push(entry);
}

operations.schema:
input AddTemplateInput {
  id: OID!
  name: String
  mode: TemplateInstanceMode!
}

operations.reducer:
const { templates } = licensingLists(state);
if (templates.some((t) => t.id === action.input.id)) {
  throw new DuplicateTemplateError(`template ${action.input.id} already exists`);
}
templates.push({
  id: action.input.id,
  name: action.input.name ?? null,
  mode: action.input.mode,
  sharedEnvironment: null,
  services: [],
  packages: [],
  size: null,
  baseDomain: null,
  packageRegistry: null,
});

const t = findTemplate(state, action.input.id);
const mode = action.input.mode ?? t.mode;
if (mode === "SHARED" && (t.services.length > 0 || t.packages.length > 0)) {
  throw new SharedTemplateServicesError(
    "a SHARED template provisions nothing; remove its services and packages first",
  );
}
t.mode = mode;
// A field that is absent (undefined or null) is left unchanged, so an
// edit of one field cannot wipe another.
if (action.input.name != null) t.name = action.input.name;
if (action.input.sharedEnvironment != null)
  t.sharedEnvironment = action.input.sharedEnvironment;
if (action.input.size != null) t.size = action.input.size;
if (action.input.baseDomain != null) t.baseDomain = action.input.baseDomain;
if (action.input.packageRegistry != null)
  t.packageRegistry = action.input.packageRegistry;

const t = findTemplate(state, action.input.templateId);
if (t.mode === "SHARED") {
  throw new SharedTemplateServicesError("a SHARED template carries no services");
}
if (t.services.some((s) => s.id === action.input.id)) {
  throw new DuplicateServiceError(`service ${action.input.id} already exists`);
}
if (action.input.artifactName && action.input.type !== "FUSION") {
  throw new ArtifactOnNonFusionServiceError(
    `only a FUSION service can reference an artifact, not ${action.input.type}`,
  );
}
t.services.push({
  id: action.input.id,
  type: action.input.type,
  prefix: action.input.prefix ?? action.input.artifactName ?? null,
  artifactName: action.input.artifactName ?? null,
  artifactChannel: action.input.artifactName
    ? (action.input.artifactChannel ?? "LATEST")
    : null,
});

operations.schema:
input RemoveTemplateServiceInput {
  templateId: OID!
  id: OID!
}

operations.reducer:
const t = findTemplate(state, action.input.templateId);
const at = t.services.findIndex((s) => s.id === action.input.id);
if (at === -1) {
  throw new UnknownServiceError(`service ${action.input.id} does not exist`);
}
t.services.splice(at, 1);

operations.schema:
input AddTemplatePackageInput {
  templateId: OID!
  id: OID!
  packageName: String!
  version: String
}

operations.reducer:
const t = findTemplate(state, action.input.templateId);
if (t.mode === "SHARED") {
  throw new SharedTemplateServicesError("a SHARED template carries no packages");
}
if (t.packages.some((p) => p.id === action.input.id)) {
  throw new DuplicatePackageError(`package ${action.input.id} already exists`);
}
t.packages.push({
  id: action.input.id,
  packageName: action.input.packageName,
  version: action.input.version ?? null,
});

operations.schema:
input RemoveTemplatePackageInput {
  templateId: OID!
  id: OID!
}

operations.reducer:
const t = findTemplate(state, action.input.templateId);
const at = t.packages.findIndex((p) => p.id === action.input.id);
if (at === -1) {
  throw new UnknownPackageError(`package ${action.input.id} does not exist`);
}
t.packages.splice(at, 1);

const { templates, terms } = licensingLists(state);
const at = templates.findIndex((t) => t.id === action.input.id);
if (at === -1) {
  throw new TemplateNotFoundError(`template ${action.input.id} does not exist`);
}
if (terms.some((t) => t.templateId === action.input.id)) {
  throw new TemplateInUseError(`template ${action.input.id} is used by a term`);
}
templates.splice(at, 1);

const { templates, terms } = licensingLists(state);
if (terms.some((t) => t.id === action.input.id)) {
  throw new DuplicateTermError(`term ${action.input.id} already exists`);
}
if (!isValidKind(action.input.kind)) {
  throw new InvalidKindError("a kind must be non-blank without surrounding spaces");
}
if (terms.some((t) => t.kind === action.input.kind)) {
  throw new DuplicateKindError(`kind ${action.input.kind} is already used by this app`);
}
if (action.input.templateId && !templates.some((t) => t.id === action.input.templateId)) {
  throw new TemplateNotFoundError(`template ${action.input.templateId} does not exist`);
}
if (action.input.validityDays != null && action.input.validityDays <= 0) {
  throw new NegativeValidityError("validityDays must be positive");
}
terms.push({
  id: action.input.id,
  kind: action.input.kind,
  label: action.input.label ?? null,
  templateId: action.input.templateId ?? null,
  validityDays: action.input.validityDays ?? null,
  issuers: [...new Set(action.input.issuers ?? [])],
  status: "DRAFT",
});

const { templates, terms } = licensingLists(state);
const term = findTerm(state, action.input.id);
const kind = action.input.kind;
if (kind != null && kind !== term.kind) {
  if (!isValidKind(kind)) {
    throw new InvalidKindError("a kind must be non-blank without surrounding spaces");
  }
  // Licences carry the kind; once one could exist, renaming orphans it.
  if (term.status !== "DRAFT") {
    throw new KindImmutableError(`term ${term.id} is ${term.status}; its kind is fixed`);
  }
  if (terms.some((t) => t.id !== term.id && t.kind === kind)) {
    throw new DuplicateKindError(`kind ${kind} is already used by this app`);
  }
}
const templateId =
  action.input.templateId != null ? action.input.templateId : term.templateId;
if (templateId && !templates.some((t) => t.id === templateId)) {
  throw new TemplateNotFoundError(`template ${templateId} does not exist`);
}
if (action.input.validityDays != null && action.input.validityDays <= 0) {
  throw new NegativeValidityError("validityDays must be positive");
}
const issuers =
  action.input.issuers != null ? [...new Set(action.input.issuers)] : term.issuers;
if (term.status === "ACTIVE" && (!templateId || issuers.length === 0)) {
  throw new TermIncompleteError("an ACTIVE term needs a template and at least one issuer");
}
if (kind != null) term.kind = kind;
if (action.input.label != null) term.label = action.input.label;
term.templateId = templateId;
if (action.input.validityDays != null)
  term.validityDays = action.input.validityDays;
term.issuers = issuers;

const term = findTerm(state, action.input.id);
if (!term.templateId || term.issuers.length === 0) {
  throw new TermIncompleteError("a term needs a template and at least one issuer to be published");
}
term.status = "ACTIVE";

const term = findTerm(state, action.input.id);
if (term.status !== "ACTIVE") {
  throw new TermNotPublishedError("only an ACTIVE term can be retired");
}
term.status = "RETIRED";
